function companyKey(v){if(v&&typeof v==='object')v=v.id||v.name||v.companyName||'';return String(v??'').trim().toLocaleLowerCase().replace(/[\s._-]+/g,'').replace(/company|কোম্পানি/g,'')}
function canonicalCompanyId(p){const vals=[p?.companyId,p?.company_id,p?.company,p?.companyName];for(let v of vals){if(v&&typeof v==='object')v=v.id||v.name||v.companyName||'';const raw=String(v??'').trim().toLocaleLowerCase(),k=companyKey(v);if(!k)continue;const exact=COMPANY_PROFILES.find(c=>c.id.toLocaleLowerCase()===raw||c.name.trim().toLocaleLowerCase()===raw);if(exact)return exact.id;if(k==='psp'){const cat=companyKey(p?.category||p?.type||'');return cat.includes('glass')||cat.includes('গ্লাস')?'glass-psp':'ss-psp'}const direct=COMPANY_PROFILES.find(c=>companyKey(c.id)===k||companyKey(c.name)===k);if(direct)return direct.id;const aliases={kai:'al-kai',altech:'al-altech',chunghua:'al-chunghua',nikki:'al-nikki',maxx:'al-maxx',steeltech:'ss-steeltech',hatim:'ss-hatim',steelking:'ss-steelking',grambangla:'ss-grambangla',nasir:'glass-nasir',akij:'glass-akij',aluminiumhardware:'al-hardware',aluminumhardware:'al-hardware',sshardware:'ss-hardware',stainlesshardware:'ss-hardware'};if(aliases[k])return aliases[k]}return ''}

function inferLegacyProductCompany(p){
 const raw=[p?.name,p?.family,p?.sku,p?.barcode,p?.category,p?.variant,p?.spec,p?.brand,p?.manufacturer,p?.supplierName,p?.description,p?.notes].filter(Boolean).join(' ').toLocaleLowerCase();
 const t=raw.replace(/[._-]+/g,' ').replace(/\s+/g,' ').trim();
 if(/glass|\bgls\b|গ্লাস/.test(t))return '';
 const has=re=>re.test(t);
 if(has(/\bss hardware\b|\bstainless hardware\b|এস এস হার্ডওয়্যার|এস এস হার্ডওয়্যার|স্টেইনলেস হার্ডওয়্যার|স্টেইনলেস হার্ডওয়্যার/))return 'ss-hardware';
 if(has(/\baluminium hardware\b|\baluminum hardware\b|অ্যালুমিনিয়াম হার্ডওয়্যার|অ্যালুমিনিয়াম হার্ডওয়্যার/))return 'al-hardware';
 if(has(/\bsteel ?tech\b|স্টিলটেক/))return 'ss-steeltech';
 if(has(/\bhatim\b|হাতিম/))return 'ss-hatim';
 if(has(/\bsteel ?king\b|স্টিল কিং/))return 'ss-steelking';
 if(has(/\bgram ?bangla\b|গ্রাম বাংলা/))return 'ss-grambangla';
 if(has(/\bpsp\b|পি এস পি|পিএসপি/)&&has(/\bss\b|stainless|স্টেইনলেস|এস এস|২০১|201|pipe|পাইপ/))return 'ss-psp';
 if(has(/\bkai company\b|\bkai\b|কাই কোম্পানি/))return 'al-kai';
 if(has(/\baltech\b|আলটেক/))return 'al-altech';
 if(has(/\bchunghua\b|\bchunghwa\b|\bchun hua\b|চুনহুয়া|চুনহুয়া/))return 'al-chunghua';
 if(has(/\bnikki\b|\bnaxx\b|নিক্কি|নিকি/))return 'al-nikki';
 if(has(/\bmaxx\b|ম্যাক্স/))return 'al-maxx';
 return '';
}

let activeCompanyId='';
function renderCompanyWorkspace(companyId){const c=COMPANY_PROFILES.find(x=>x.id===companyId);if(!c)return;activeCompanyId=companyId;const products=db.products.filter(p=>productBelongsToCompany(p,companyId)),purchases=(db.purchases||[]).filter(x=>x.companyId===companyId),sales=(db.sales||[]).filter(x=>x.companyId===companyId);const sum=(arr,key)=>arr.reduce((n,x)=>n+(Number(x[key])||0),0);const host=$('companyWorkspaceContent');if(!host)return;host.innerHTML='<div class="row"><div><h2>'+esc(c.name)+'</h2><div class="muted small">'+esc(c.type)+' • আলাদা কোম্পানি হিসাব</div></div><button type="button" class="secondary right" data-jump="dashboard">← ড্যাশবোর্ড</button></div><div class="stats"><div class="stat"><small>পণ্য ভ্যারিয়েন্ট</small><strong>'+products.length.toLocaleString('bn-BD')+'</strong></div><div class="stat"><small>মোট স্টক (একক যোগফল)</small><strong>'+sum(products,'stock').toLocaleString('bn-BD')+'</strong></div><div class="stat"><small>ক্রয় মোট</small><strong>'+money(sum(purchases,'total'))+'</strong></div><div class="stat"><small>বিক্রয় মোট</small><strong>'+money(sum(sales,'total'))+'</strong></div></div><div class="actions" style="margin:12px 0"><button type="button" data-company-action="purchase">এই কোম্পানির ক্রয়</button><button type="button" data-company-action="sale">এই কোম্পানির বিক্রয়</button><button type="button" class="secondary" data-company-print>স্টক/মূল্য তালিকা প্রিন্ট</button><button type="button" class="secondary" data-company-export="'+c.id+'">CSV / Excel তালিকা</button></div><div class="card"><h3>পণ্য, মূল্য ও স্টক</h3><div class="table-wrap"><table><thead><tr><th>পণ্য</th><th>গ্রেড/সাইজ/রং</th><th>একক</th><th>স্টক</th><th>ক্রয়</th><th>খুচরা</th><th>পাইকারি</th></tr></thead><tbody>'+products.map(p=>'<tr><td>'+esc(productLabel(p))+'</td><td>'+esc([p.variant,p.size,p.color,p.thickness].filter(Boolean).join(' / '))+'</td><td>'+esc(p.unit||'')+'</td><td>'+Number(p.stock||0).toLocaleString('bn-BD')+'</td><td>'+money(p.cost)+'</td><td>'+money(p.retail)+'</td><td>'+money(p.wholesale)+'</td></tr>').join('')+'</tbody></table></div></div><div class="grid"><div class="card"><h3>ক্রয় ইতিহাস</h3><div class="table-wrap"><table><thead><tr><th>তারিখ</th><th>পণ্য</th><th>পরিমাণ</th><th>মোট</th></tr></thead><tbody>'+purchases.map(x=>'<tr><td>'+esc(x.date||'')+'</td><td>'+esc(x.productName||'')+'</td><td>'+Number(x.qty||0)+'</td><td>'+money(x.total)+'</td></tr>').join('')+'</tbody></table></div></div><div class="card"><h3>বিক্রয় ইতিহাস ও ভাউচার</h3><div class="table-wrap"><table><thead><tr><th>তারিখ</th><th>ইনভয়েস</th><th>কাস্টমার</th><th>মোট</th><th>বাকি</th><th>ভাউচার</th></tr></thead><tbody>'+sales.map(x=>'<tr><td>'+esc(x.date||'')+'</td><td>'+esc(x.invoice||'')+'</td><td>'+esc(x.customerName||'')+'</td><td>'+money(x.total)+'</td><td>'+money(x.due)+'</td><td><button type="button" class="secondary" data-company-voucher="'+x.id+'">WhatsApp</button></td></tr>').join('')+'</tbody></table></div></div></div>';}
document.body.addEventListener('click',e=>{const tile=e.target.closest('[data-open-company]');if(tile){renderCompanyWorkspace(tile.dataset.openCompany);go('companyWorkspace');return}const action=e.target.closest('[data-company-action]');if(action&&activeCompanyId){if(action.dataset.companyAction==='purchase'){$('buyCompany').value=activeCompanyId;refreshCompanyProductOptions();go('purchases')}else{$('saleCompany').value=activeCompanyId;refreshCompanyProductOptions();go('sales')}return}const ex=e.target.closest('[data-company-export]');if(ex){exportCompanyCsv(ex.dataset.companyExport);return}if(e.target.closest('[data-company-print]')){const w=window.open('','_blank');if(!w){alert('প্রিন্ট পেজ খুলতে পপ-আপ অনুমতি দিন');return}w.document.write('<!doctype html><html lang="bn"><meta charset="utf-8"><title>কোম্পানি স্টক</title><style>body{font:13px system-ui;padding:20px}h2{text-align:center}table{width:100%;border-collapse:collapse}th,td{border:1px solid #999;padding:6px;text-align:left}@media print{button{display:none}}</style>'+($('companyWorkspaceContent')?.innerHTML||'')+'<script>window.onload=()=>window.print()<\\/script></html>');w.document.close();return}const v=e.target.closest('[data-company-voucher]');if(v){const sale=(db.sales||[]).find(x=>x.id===v.dataset.companyVoucher);if(!sale)return;const phone=prompt('কাস্টমারের WhatsApp নম্বর দিন (দেশের কোডসহ, যেমন 8801XXXXXXXXX)');if(!phone)return;const digits=phone.replace(/\\D/g,'');if(digits.length<10){alert('সঠিক মোবাইল নম্বর দিন');return}const msg='মদিনা থাই অ্যালুমিনিয়াম এন্ড এস এস গ্যালারি\\nইনভয়েস: '+(sale.invoice||'')+'\\nতারিখ: '+(sale.date||'')+'\\nকাস্টমার: '+(sale.customerName||'')+'\\nপণ্য: '+(sale.productName||'')+'\\nপরিমাণ: '+(sale.qty||'')+' '+(sale.unit||'')+'\\nমোট: '+(sale.total||0)+' টাকা\\nজমা: '+(sale.paid||0)+' টাকা\\nবাকি: '+(sale.due||0)+' টাকা';window.open('https://wa.me/'+digits+'?text='+encodeURIComponent(msg),'_blank');}});
function renderCompanyExportButtons(){const host=$('companyExportButtons');if(!host)return;host.innerHTML=COMPANY_PROFILES.map(c=>{const count=db.products.filter(p=>productBelongsToCompany(p,c.id)).length;return `<button type="button" class="secondary" data-export-company="${c.id}">${c.name} (${count}) — CSV ডাউনলোড</button>`}).join('')}function exportCompanyCsv(companyId){const c=COMPANY_PROFILES.find(x=>x.id===companyId);if(!c)return;const rows=db.products.filter(p=>productBelongsToCompany(p,companyId));if(!rows.length){alert(c.name+'-এর তালিকায় কোনো পণ্য নেই। আগে সব কোম্পানির পণ্যের তালিকা তৈরি করুন।');return}const cols=[['name','পণ্যের নাম'],['sku','SKU'],['category','ক্যাটাগরি'],['family','পরিবার'],['variant','গ্রেড/ভ্যারিয়েন্ট'],['size','সাইজ'],['color','রং'],['thickness','পুরুত্ব'],['spec','বিবরণ'],['unit','একক'],['cost','ক্রয়মূল্য'],['retail','খুচরা মূল্য'],['wholesale','পাইকারি মূল্য'],['stock','স্টক']];const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv='\\uFEFF'+[cols.map(x=>q(x[1])).join(','),...rows.map(p=>cols.map(x=>q(p[x[0]])).join(','))].join('\\r\\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(c.name.replace(/[^a-zA-Z0-9\\u0980-\\u09FF-]+/g,'_')||c.id)+'_products.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}document.addEventListener('click',e=>{const b=e.target.closest('[data-export-company]');if(b)exportCompanyCsv(b.dataset.exportCompany)});
