const inRange=d=>{let x=reportDate(d);return x&&x>=start&&x<=end};const sales=db.sales.filter(x=>inRange(x.date)),expenses=db.expenses.filter(x=>inRange(x.date));const saleTotal=sales.reduce((n,x)=>n+(Number(x.total)||0),0),salePaid=sales.reduce((n,x)=>n+(Number(x.paid)||0),0),saleDue=sales.reduce((n,x)=>n+(Number(x.due)||0),0),other=expenses.filter(x=>x.type==='অন্যান্য আয়').reduce((n,x)=>n+(Number(x.amount)||0),0),cost=expenses.filter(x=>x.type==='ব্যয়').reduce((n,x)=>n+(Number(x.amount)||0),0),gross=sales.reduce((n,x)=>n+(Number(x.total)||0)-(Number(x.costTotal)||0),0),jobAdvance=db.jobs.filter(j=>inRange(j.date)).reduce((n,j)=>n+(Number(j.advance)||0),0),jobPayments=db.jobs.reduce((n,j)=>(j.payments||[]).filter(p=>inRange(p.date)&&p.note!=='আগের অগ্রিম').reduce((a,p)=>a+(Number(p.amount)||0),n),0),received=salePaid+jobAdvance+jobPayments+expenses.filter(x=>x.type==='কাস্টমার থেকে বকেয়া আদায়').reduce((n,x)=>n+(Number(x.amount)||0),0);$('periodSales').textContent=money(saleTotal);$('periodReceived').textContent=money(received);$('periodOtherIncome').textContent=money(other);$('periodExpense').textContent=money(cost);$('periodProfit').textContent=money(gross+other-cost);$('periodDue').textContent=money(saleDue);$('periodCaption').textContent=label+' • কাজের কিস্তি/অগ্রিমসহ আদায়';
