  const isHardware=cat.includes('হার্ডওয়্যার')||cat.includes('হার্ডওয়্যার')||cat.includes('hardware')||label.includes('হার্ডওয়্যার')||label.includes('হার্ডওয়্যার')||label.includes('hardware');
