$('estimateHistoryRows').addEventListener('click',e=>{const p=e.target.closest('[data-est-print]'),w=e.target.closest('[data-est-share]');if(p){const x=db.purchaseEstimates.find(v=>v.id===p.dataset.estPrint);if(x)printPurchaseEstimate(x)}if(w){const x=db.purchaseEstimates.find(v=>v.id===w.dataset.estShare);if(x){const n=String(x.phone||'').replace(/[^0-9]/g,'');const target=n?(n.startsWith('0')?'88'+n:n):'';window.open('https://wa.me/'+target+'?text='+encodeURIComponent(estimateMessage(x)),'_blank')}}});
$('purchaseForm').onsubmit=e=>{e.preventDefault();let p=db.products.find(x=>x.id===$('buyProduct').value&&x.companyId===$('buyCompany').value),q=+$('buyQty').value,price=+$('buyPrice').value;if(!p||q<=0)return alert('পণ্য ও পরিমাণ ঠিক করুন');const editId=$('purchaseEditId').value,old=editId?db.purchases.find(x=>x.id===editId):null;if(editId&&!old)return alert('ক্রয় রেকর্ড পাওয়া যায়নি');if(old){const op=db.products.find(x=>x.id===old.productId)||db.products.find(x=>productLabel(x)===old.productName&&(x.companyId||'legacy')===(old.companyId||'legacy'));if(op){if(Number(op.stock||0)<Number(old.qty||0))return alert('পুরোনো ক্রয়ের স্টক সমন্বয় সম্ভব নয়; আগে স্টক মিলিয়ে নিন।');op.stock=Number(op.stock||0)-Number(old.qty||0)}}const rec={id:old?.id||id(),productId:p.id,date:date(),companyId:p.companyId,companyName:companyName(p.companyId),productName:productLabel(p),qty:q,unitPrice:price,total:q*price,supplier:$('buySupplier').value};if(old)Object.assign(old,rec);else db.purchases.push(rec);p.stock=Number(p.stock||0)+q;p.cost=price;$('purchaseEditId').value='';e.target.reset();e.target.querySelector('button[type=submit]').textContent='ক্রয় সংরক্ষণ ও স্টক বাড়ান';save()};
function updateSalePrice(){let p=db.products.find(x=>x.id===$('saleProduct').value);if(!p)return;let u=$('saleUnit').value,m=u==='box'?p.box:u==='bundle'?p.bundle:1;if(u!=='base'&&m<=0){$('saleMessage').textContent='এই পণ্যের জন্য '+u+' conversion সেট করা নেই।';$('salePrice').value=0;return}$('salePrice').value=($('saleType').value==='wholesale'?p.wholesale:p.retail)*m;$('saleMessage').textContent=`প্রতি ${u==='base'?p.unit:u} = ${m} ${p.unit}`;calcTotal()}['saleProduct','saleUnit','saleType'].forEach(x=>$(x).addEventListener('change',updateSalePrice));$('buyCompany').addEventListener('change',refreshCompanyProductOptions);$('saleCompany').addEventListener('change',refreshCompanyProductOptions);['saleQty','salePrice','saleDiscount'].forEach(x=>$(x).addEventListener('input',calcTotal));function calcTotal(){let subtotal=+$('saleQty').value*+$('salePrice').value,discount=Math.min(100,Math.max(0,+$('saleDiscount').value||0)),off=subtotal*discount/100,t=subtotal-off;$('saleTotal').textContent='মোট: '+money(t)+' (ছাড়: '+money(off)+')'}$('saleBarcode').addEventListener('change',()=>{let p=db.products.find(x=>x.barcode===$('saleBarcode').value.trim()||x.sku===$('saleBarcode').value.trim());if(p&&p.companyId===$('saleCompany').value){$('saleProduct').value=p.id;updateSalePrice();$('saleQty').focus()}else if(p){alert('এই পণ্যটি নির্বাচিত কোম্পানির স্টকে নেই। কোম্পানি পরিবর্তন করুন।')}else alert('এই বারকোডের পণ্য পাওয়া যায়নি')});$('saleForm').onsubmit=e=>{e.preventDefault();let p=db.products.find(x=>x.id===$('saleProduct').value&&x.companyId===$('saleCompany').value),qty=+$('saleQty').value,unit=$('saleUnit').value,m=unit==='box'?p?.box:unit==='bundle'?p?.bundle:1;if(!p||qty<=0||m<=0)return alert('পণ্য/পরিমাণ/ইউনিট পরীক্ষা করুন');let baseQty=qty*m,subtotal=qty*+$('salePrice').value,discountPercent=Math.min(100,Math.max(0,+$('saleDiscount').value||0)),discountAmount=subtotal*discountPercent/100,total=subtotal-discountAmount,paid=+$('salePaid').value,editId=$('saleEditId').value,old=editId?db.sales.find(x=>x.id===editId):null;if(editId&&!old)return alert('বিক্রয় রেকর্ড পাওয়া যায়নি');const op=old?(db.products.find(x=>x.id===old.productId)||db.products.find(x=>productLabel(x)===old.productName&&(x.companyId||'legacy')===(old.companyId||'legacy'))):null;if(old&&op)op.stock=Number(op.stock||0)+Number(old.baseQty??old.qty??0);if(baseQty>Number(p.stock||0)){if(old&&op)op.stock=Math.max(0,Number(op.stock||0)-Number(old.baseQty??old.qty??0));return alert('পর্যাপ্ত স্টক নেই। বর্তমান স্টক: '+p.stock+' '+p.unit)}if(paid>total){if(old&&op)op.stock=Math.max(0,Number(op.stock||0)-Number(old.baseQty??old.qty??0));return alert('জমার টাকা মোটের চেয়ে বেশি')}p.stock=Number(p.stock||0)-baseQty;let customer=db.customers.find(c=>c.id===$('saleCustomer').value);let rec={id:old?.id||id(),productId:p.id,companyId:p.companyId,companyName:companyName(p.companyId),invoice:old?.invoice||'MBM-'+Date.now().toString().slice(-8),date:date(),customerId:customer?.id||'',customerName:customer?.name||'সাধারণ কাস্টমার',productName:productLabel(p),qty,unit:unit==='base'?p.unit:unit,baseQty,subtotal,discountPercent,discountAmount,total,paid,due:total-paid,costTotal:baseQty*p.cost};if(old)Object.assign(old,rec);else db.sales.push(rec);$('saleEditId').value='';save();showInvoice(rec);e.target.reset();$('saleQty').value=1;e.target.querySelector('button[type=submit]').textContent='বিক্রয় সম্পন্ন ও ইনভয়েস'};
function printJobSlip(j){if(!j)return;const w=window.open('','_blank','width=800,height=900');if(!w){alert('প্রিন্ট স্লিপ খুলতে পপ-আপ অনুমতি দিন');return}const bal=j.balance??(j.total-j.advance);w.document.write(`<!doctype html><html lang="bn"><meta charset="utf-8"><title>কাজের স্লিপ</title><style>body{font:15px system-ui;padding:24px;color:#17251c}h2{text-align:center;margin-bottom:4px}.muted{color:#64746a}.line{border-bottom:1px solid #bbb;padding:10px 0}.amount{font-size:18px;font-weight:bold}@media print{button{display:none}}</style><h2>${esc(db.settings.name||'মদিনা থাই অ্যালুমিনিয়াম এন্ড এস এস গ্যালারি')}</h2><p style="text-align:center">${esc(db.settings.address||'')} ${esc(db.settings.phone||'')}</p><hr><h3>কাজের অর্ডার স্লিপ</h3><div class="line">তারিখ: ${esc(j.date||'')}　অবস্থা: ${esc(j.status||'')}</div><div class="line">কাস্টমার: <b>${esc(j.customer)}</b><br>মোবাইল: ${esc(j.phone||'')}<br>কাজের ঠিকানা: ${esc(j.address||'')}</div><div class="line">কাজের ধরন: ${esc(j.type||'')}<br>মাপ: ${esc(j.measure||'')}<br>মালামাল/বিবরণ: ${esc(j.material||'')}</div><div class="line amount">মোট: ${money(j.total)}　অগ্রিম: ${money(j.advance)}　বাকি: ${money(bal)}</div><p style="margin-top:55px">কাস্টমারের স্বাক্ষর: __________________　কর্তৃপক্ষ: __________________</p><button onclick="window.print()">প্রিন্ট করুন</button></html>`);w.document.close();w.focus()}
function showInvoice(s){if(!s)return;document.body.classList.remove('print-a4','print-thermal80','print-thermal58');document.body.classList.add('print-'+$('invoiceSize').value);const rate=s.qty?Number(s.subtotal!==undefined?s.subtotal:s.total)/Number(s.qty):Number(s.total||0);$('invoiceContent').innerHTML='<div style="text-align:center"><h2>'+esc(db.settings.name||'মদিনা থাই অ্যালুমিনিয়াম এন্ড এস এস গ্যালারি')+'</h2><p>'+esc(db.settings.address||'')+'<br>'+esc(db.settings.phone||'')+'</p><b>থাই অ্যালুমিনিয়াম • স্টেইনলেস স্টিল • গ্লাস • হার্ডওয়্যার</b><hr></div><p>ইনভয়েস: <b>'+esc(s.invoice)+'</b><br>তারিখ: '+esc(s.date)+'<br>কাস্টমার: '+esc(s.customerName||'—')+'</p><table style="width:100%;border-collapse:collapse"><thead><tr><th>পণ্যের বিবরণ / গ্রেড / মাপ</th><th>পরিমাণ</th><th>একক দর</th><th>মোট</th></tr></thead><tbody><tr><td>'+esc(s.productName)+'</td><td>'+s.qty+' '+esc(s.unit||'')+'</td><td>'+money(rate)+'</td><td>'+money(s.subtotal!==undefined?s.subtotal:s.total)+'</td></tr></tbody></table><h3 style="text-align:right">'+(s.subtotal!==undefined?'সাবটোটাল: '+money(s.subtotal)+'<br>ছাড় ('+(s.discountPercent||0)+'%): '+money(s.discountAmount||0)+'<br>':'')+'সর্বমোট: '+money(s.total)+'<br>জমা: '+money(s.paid)+'<br>বাকি: '+money(s.due)+'</h3><p style="text-align:center">মালামাল বুঝে নিন। ধন্যবাদ, আবার আসবেন।</p><p style="display:flex;justify-content:space-between;margin-top:36px"><span>ক্রেতার স্বাক্ষর: __________</span><span>বিক্রেতার স্বাক্ষর: __________</span></p>';$('invoiceModal').classList.add('show')}

function refreshLedgerJobs(){const cid=$('ledgerCustomer').value,c=db.customers.find(x=>x.id===cid);const norm=v=>String(v||'').replace(/\\D/g,'');const name=v=>String(v||'').trim().toLocaleLowerCase();const jobs=cid?db.jobs.filter(j=>j.customerId===cid||(c&&(!j.customerId&&((norm(j.phone)&&norm(c.phone)&&norm(j.phone)===norm(c.phone))||name(j.customer)===name(c.name))))):[];jobs.forEach(j=>{if(!j.customerId&&c)j.customerId=cid});$('ledgerJob').innerHTML='<option value="">'+(jobs.length?'কাজ নির্বাচন করুন':'এই কাস্টমারের কোনো কাজের অর্ডার নেই')+'</option>'+jobs.map(j=>`<option value="${j.id}">${esc(j.type||'কাজ')} • ${esc(j.date||'')} • বাকি ${money(Math.max(0,Number(j.total||0)-Number(j.paidTotal??j.advance??0)))}</option>`).join('');renderLedger()}$('ledgerCustomer').onchange=refreshLedgerJobs;function renderLedger(){const cid=$('ledgerCustomer').value,c=db.customers.find(x=>x.id===cid);if(!c){$('ledgerSummary').textContent='কাস্টমার নির্বাচন করলে হিসাব দেখা যাবে।';$('ledgerRows').innerHTML='';return}const jobs=db.jobs.filter(j=>j.customerId===cid),sales=db.sales.filter(s=>s.customerId===cid),jobTotal=jobs.reduce((a,j)=>a+Number(j.total||0),0),jobPaid=jobs.reduce((a,j)=>a+Number(j.paidTotal??j.advance??0),0),jobDue=jobs.reduce((a,j)=>a+Math.max(0,Number(j.total||0)-Number(j.paidTotal??j.advance??0)),0),saleDue=sales.reduce((a,s)=>a+Number(s.due||0),0);$('ledgerSummary').innerHTML=`<b>${esc(c.name)}</b> — কাজের মোট ${money(jobTotal)} • কাজের জমা ${money(jobPaid)} • কাজের বাকি ${money(jobDue)} • বিক্রয়ের বাকি ${money(saleDue)} • <b>সর্বমোট বাকি ${money(jobDue+saleDue)}</b>`;const rows=jobs.flatMap(j=>(j.payments||[]).map(p=>({date:p.date,job:j.type,detail:p.note||'কিস্তি জমা',amount:p.amount,balance:p.balanceAfter??''})));$('ledgerRows').innerHTML=rows.sort((a,b)=>String(a.date).localeCompare(String(b.date))).reverse().map(p=>`<tr><td>${esc(p.date)}</td><td>${esc(p.job)}</td><td>${esc(p.detail)}</td><td>${money(p.amount)}</td><td>${p.balance===''?'—':money(p.balance)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">এখনো কোনো অতিরিক্ত জমা নেই।</td></tr>'}document.body.addEventListener('click',e=>{const b=e.target.closest('[data-ledger-open]');if(b){$('ledgerCustomer').value=b.dataset.ledgerOpen;$('ledgerCustomer').dispatchEvent(new Event('change'));$('ledgerAmount').focus()}});$('ledgerSave').onclick=()=>{const j=db.jobs.find(x=>x.id===$('ledgerJob').value),amount=+$('ledgerAmount').value;if(!j)return alert('আগে কাস্টমার ও কাজ নির্বাচন করুন।');if(amount<=0)return alert('জমার পরিমাণ লিখুন।');const paid=Number(j.paidTotal??j.advance??0),balance=Math.max(0,Number(j.total||0)-paid);if(amount>balance)return alert('জমার টাকা বাকি টাকার চেয়ে বেশি হতে পারবে না। বাকি '+money(balance));j.payments=j.payments||[];const next=paid+amount;j.payments.push({id:id(),date:$('ledgerDate').value||date(),amount,note:$('ledgerNote').value.trim(),balanceAfter:Math.max(0,Number(j.total||0)-next)});j.paidTotal=next;j.balance=Math.max(0,Number(j.total||0)-next);save();$('ledgerAmount').value='';$('ledgerNote').value='';$('ledgerCustomer').dispatchEvent(new Event('change'));alert('টাকা জমা ও বাকি হিসাব আপডেট হয়েছে।')};
function ensureEditField(formId,idName){const f=$(formId);if(f&&!$(idName)){const x=document.createElement('input');x.type='hidden';x.id=idName;f.appendChild(x)}}
[['customerForm','cEditId'],['supplierForm','sEditId'],['jobForm','jEditId'],['expenseForm','eEditId'],['staffForm','staffEditId']].forEach(x=>ensureEditField(x[0],x[1]));
ensureEditField('staffPayForm','staffPayEditId');
function resetEditForm(formId,idName,buttonId,buttonText){const f=$(formId);if(!f)return;f.reset();if($(idName))$(idName).value='';const b=f.querySelector('button[type="submit"]');if(b)b.textContent=buttonText||'সংরক্ষণ';}
function ensureHiddenField(formId,id){const f=$(formId);if(f&&!$(id)){const x=document.createElement('input');x.type='hidden';x.id=id;f.appendChild(x)}}
