function trashRecord(kind,item){db.trash=db.trash||[];db.trash.push({trashId:id(),kind,record:JSON.parse(JSON.stringify(item)),deletedAt:new Date().toISOString()})}
function restoreTrashItem(tid){db.trash=db.trash||[];const t=db.trash.find(x=>x.trashId===tid);if(!t)return;const r=t.record;if(t.kind==='products'){db.products.push(r);db.archivedProducts=(db.archivedProducts||[]).filter(x=>x.id!==r.id)}else if(t.kind==='purchases'){const p=db.products.find(x=>x.id===r.productId);if(p)p.stock=Number(p.stock||0)+Number(r.qty||0);db.purchases.push(r)}else if(t.kind==='sales'){const p=db.products.find(x=>x.id===r.productId);if(p){const q=Number(r.baseQty??r.qty??0);if(q>Number(p.stock||0))return alert('এই বিক্রয় ফিরিয়ে আনতে পর্যাপ্ত স্টক নেই।');p.stock=Number(p.stock||0)-q}db.sales.push(r)}else if(['customers','suppliers','jobs','expenses','staff','staffPayments','staffAttendance','orders'].includes(t.kind))db[t.kind].push(r);else return;db.trash=db.trash.filter(x=>x.trashId!==tid);save()}
function renderTrash(){const host=$('recycleBinRows');if(!host)return;db.trash=db.trash||[];const labels={products:'পণ্য',purchases:'ক্রয়',sales:'বিক্রয়',customers:'কাস্টমার',suppliers:'সাপ্লায়ার',jobs:'কাজের অর্ডার',expenses:'আয়-ব্যয়',staff:'স্টাফ',staffPayments:'স্টাফ বেতন',staffAttendance:'উপস্থিতি',orders:'অর্ডার'};host.innerHTML=db.trash.slice().reverse().map(t=>{const r=t.record||{},n=r.name||r.productName||r.customerName||r.customer||r.desc||r.invoice||r.supplier||'';return '<tr><td>'+esc(labels[t.kind]||t.kind)+'</td><td>'+esc(n)+'</td><td>'+esc(new Date(t.deletedAt).toLocaleString('bn-BD'))+'</td><td><button class="secondary" data-restore-trash="'+t.trashId+'">পুনরুদ্ধার</button></td></tr>'}).join('')||'<tr><td colspan="4" class="empty">মুছে ফেলা তথ্য নেই</td></tr>'}
function editRecord(kind,idValue){
 const map={customers:['customerForm','cEditId',{name:'cName',phone:'cPhone',address:'cAddress'}],suppliers:['supplierForm','sEditId',{name:'sName',phone:'sPhone',address:'sAddress'}],jobs:['jobForm','jEditId',{customer:'jCustomer',phone:'jPhone',address:'jAddress',type:'jType',measure:'jMeasure',material:'jMaterial',total:'jTotal',advance:'jAdvance',status:'jStatus',date:'jDate'}],expenses:['expenseForm','eEditId',{type:'eType',desc:'eDesc',amount:'eAmount',date:'eDate'}],staff:['staffForm','staffEditId',{name:'staffName',phone:'staffPhone',role:'staffRole',salary:'staffSalary'}]};
 const cfg=map[kind],item=(db[kind]||[]).find(x=>x.id===idValue);if(!cfg||!item)return;
 const [formId,hidden,fields]=cfg;$(hidden).value=item.id;Object.entries(fields).forEach(([key,id])=>{if($(id))$(id).value=item[key]??''});
 const form=$(formId),btn=form?.querySelector('button[type="submit"]');if(btn)btn.textContent='সংশোধন সংরক্ষণ';go(kind==='customers'?'customers':kind==='suppliers'?'suppliers':kind==='jobs'?'jobs':kind==='expenses'?'expenses':'staff');form?.scrollIntoView({behavior:'smooth',block:'center'});
}
function removeRecord(kind,idValue){if(!confirm('এই তথ্যটি রিসাইকেল বিনে পাঠাবেন? পরে ফিরিয়ে আনতে পারবেন।'))return;if(kind==='staff'&&((db.staffPayments||[]).some(x=>x.staffId===idValue)||(db.staffAttendance||[]).some(x=>x.staffId===idValue)))return alert('আগে এই স্টাফের বেতন ও উপস্থিতির রেকর্ড আলাদাভাবে রিসাইকেল বিনে পাঠান।');if(kind==='customers'&&((db.jobs||[]).some(x=>x.customerId===idValue)||(db.sales||[]).some(x=>x.customerId===idValue)))return alert('এই কাস্টমারের কাজ/বিক্রয়ের ইতিহাস আছে। আগে সংশ্লিষ্ট রেকর্ড আলাদাভাবে সরান।');const item=(db[kind]||[]).find(x=>x.id===idValue);if(!item)return;trashRecord(kind,item);db[kind]=db[kind].filter(x=>x.id!==idValue);save()}
document.body.addEventListener('click',e=>{const payEdit=e.target.closest('[data-edit-staffpay]');if(payEdit){const p=db.staffPayments.find(x=>x.id===payEdit.dataset.editStaffpay);if(!p)return;$('staffPayEditId').value=p.id;$('staffPayPerson').value=p.staffId;$('staffPayMonth').value=p.month;$('staffPayType').value=p.type;$('staffPayAmount').value=p.amount;$('staffPayDate').value=p.date;$('staffPayNote').value=p.note||'';const b=$('staffPayForm').querySelector('button[type="submit"]');if(b)b.textContent='সংশোধন সংরক্ষণ';go('staff');$('staffPayForm').scrollIntoView({behavior:'smooth',block:'center'});return}const payDel=e.target.closest('[data-remove-staffpay]');if(payDel){if(confirm('এই বেতন/অগ্রিম লেনদেনটি রিসাইকেল বিনে পাঠাবেন?')){const x=db.staffPayments.find(x=>x.id===payDel.dataset.removeStaffpay);if(x)trashRecord('staffPayments',x);db.staffPayments=db.staffPayments.filter(x=>x.id!==payDel.dataset.removeStaffpay);save()}return}const b=e.target.closest('[data-edit-record]');if(b){editRecord(b.dataset.editRecord,b.dataset.id);return}const d=e.target.closest('[data-remove-record]');if(d){removeRecord(d.dataset.removeRecord,d.dataset.id);return}});
